SELECT COUNT(order_id) AS canceled_orders_count
FROM orders
WHERE order_status = 'canceled';

SELECT COUNT(seller_id) AS seller_count
FROM sellers
WHERE seller_state = 'SP';

SELECT COUNT(DISTINCT product_category_name)
FROM products
WHERE product_category_name NOT IN (
  SELECT product_category_name
  FROM category_translation
);

SELECT AVG(total_order_value) AS average_order_value
FROM (
  SELECT order_id, SUM(price) AS total_order_value
  FROM order_items
  GROUP BY order_id
) AS order_values;

SELECT payment_type, AVG(payment_installments) AS average_installments
FROM order_payments
GROUP BY payment_type;

SELECT COUNT(order_id) AS total_orders
FROM orders
WHERE order_status IN ('created', 'processing', 'shipped', 'delivered', 'unavailable');

SELECT AVG(DATEDIFF(order_delivered_customer_date, order_estimated_delivery_date)) AS average_delay_days
FROM orders
WHERE order_status = 'delivered';

SELECT COUNT(*) 
FROM stg_orders 
WHERE delivery_delay_days > 20;

SELECT SUM(payment_value) AS total_payment_value
FROM order_payments
WHERE order_id = '0016dfedd97fc2950e388d2971d718c7';

SELECT COUNT(order_id) 
FROM orders 
WHERE order_delivered_customer_date IS NULL;

SELECT AVG(product_weight_g) AS average_weight_g
FROM products
WHERE product_weight_g IS NOT NULL;

SELECT COUNT(DISTINCT order_item_id)
FROM order_items
WHERE order_item_id NOT IN (SELECT CAST(product_id AS VARCHAR) FROM products);

SELECT SUM(order_value) AS total_payment_value
FROM orders
WHERE order_id NOT IN (SELECT order_id FROM order_payments);

SELECT AVG(geolocation_lat) AS average_latitude
FROM geolocation
WHERE geolocation_zip_code_prefix = '24220';
